import {uid,wall} from './model.js';
// Raster line evidence, not semantic recognition. All output requires review.
export function detectLines({data,width,height},crop={x:0,y:0,w:width,h:height},{minLength=35,threshold=135}={}){
 const black=(x,y)=>{const n=(y*width+x)*4;return data[n+3]>80&&(data[n]+data[n+1]+data[n+2])/3<threshold;},runs=[];
 const scan=(horizontal)=>{const end=horizontal?crop.y+crop.h:crop.x+crop.w,start=horizontal?crop.y:crop.x,lo=horizontal?crop.x:crop.y,hi=horizontal?crop.x+crop.w:crop.y+crop.h;
  for(let a=Math.ceil(start);a<end;a++){let from=-1,last=-1;for(let b=Math.ceil(lo);b<=hi;b++){const dark=b<hi&&black(horizontal?b:a,horizontal?a:b);if(dark){if(from<0)from=b;last=b;}if((!dark&&b-last>2)||b===hi){if(from>=0&&last-from>=minLength)runs.push({axis:horizontal?'h':'v',at:a,start:from,end:last});from=-1;}}}
 };scan(true);scan(false);
 const merged=[];for(const r of runs.sort((a,b)=>a.axis.localeCompare(b.axis)||a.at-b.at||a.start-b.start)){const g=merged.find(m=>m.axis===r.axis&&r.at-m.maxAt<=2&&Math.min(m.end,r.end)-Math.max(m.start,r.start)>.85*Math.min(m.end-m.start,r.end-r.start));if(g){g.maxAt=r.at;g.end=Math.max(g.end,r.end);g.start=Math.min(g.start,r.start);}else merged.push({...r,maxAt:r.at});}
 const lines=[];const used=new Set();for(let i=0;i<merged.length;i++){if(used.has(i))continue;const a=merged[i];const j=merged.findIndex((b,n)=>n>i&&!used.has(n)&&b.axis===a.axis&&b.at-a.maxAt>=3&&b.at-a.maxAt<=12&&Math.min(a.end,b.end)-Math.max(a.start,b.start)>.8*Math.min(a.end-a.start,b.end-b.start));if(j>=0){used.add(j);const b=merged[j];lines.push({axis:a.axis,at:(a.at+b.maxAt)/2,start:Math.max(a.start,b.start),end:Math.min(a.end,b.end),thickness:b.maxAt-a.at,confidence:.7,evidence:'Parallel dark lines; could also be stairs or drawing annotations.'});}else if(a.maxAt-a.at>=2)lines.push({...a,at:(a.at+a.maxAt)/2,thickness:a.maxAt-a.at+1,confidence:.45,evidence:'Thick continuous line; classification unknown.'});}
 return lines.slice(0,500);
}
export function linesToFloor(lines,{metersPerPixel,origin={x:0,y:0},name='Detected floor'}){if(!Number.isFinite(metersPerPixel)||metersPerPixel<=0||metersPerPixel>.5)throw Error('Calibrate a known distance first.');const walls=lines.filter(l=>(l.end-l.start)*metersPerPixel>=.4).map(l=>{const a=l.axis==='h'?[l.start,l.at,l.end,l.at]:[l.at,l.start,l.at,l.end];return {...wall((a[0]-origin.x)*metersPerPixel,(a[1]-origin.y)*metersPerPixel,(a[2]-origin.x)*metersPerPixel,(a[3]-origin.y)*metersPerPixel),thickness:Math.max(.06,Math.min(.5,l.thickness*metersPerPixel)),classification:'unclassified',locked:true,detection:{confidence:l.confidence,evidence:l.evidence,reviewed:false}};});return {id:uid(),name,elevation:0,rooms:[],walls,items:[],blueprint:null,features:[]};}
export function enclosedRooms(f,{cell=.12,minArea=2}={}){if(!f.walls.length)return[];const xs=f.walls.flatMap(w=>[w.x1,w.x2]),zs=f.walls.flatMap(w=>[w.z1,w.z2]),x=Math.min(...xs)-cell*2,z=Math.min(...zs)-cell*2,w=Math.max(...xs)-x+cell*2,d=Math.max(...zs)-z+cell*2,nx=Math.ceil(w/cell),nz=Math.ceil(d/cell);if(nx*nz>300000)return[];const blocked=new Uint8Array(nx*nz),seen=new Uint8Array(nx*nz);for(let j=0;j<nz;j++)for(let i=0;i<nx;i++){const px=x+(i+.5)*cell,pz=z+(j+.5)*cell;for(const wall of f.walls){const dx=wall.x2-wall.x1,dz=wall.z2-wall.z1,L=dx*dx+dz*dz,t=Math.max(0,Math.min(1,((px-wall.x1)*dx+(pz-wall.z1)*dz)/L));if(Math.hypot(px-wall.x1-t*dx,pz-wall.z1-t*dz)<=wall.thickness/2+cell*.7){blocked[j*nx+i]=1;break;}}}
 const rooms=[];for(let start=0;start<blocked.length;start++){if(blocked[start]||seen[start])continue;const queue=[start];seen[start]=1;let edge=false,ix=nx,iz=nz,ax=0,az=0;for(let n=0;n<queue.length;n++){const q=queue[n],i=q%nx,j=Math.floor(q/nx);edge ||=i===0||j===0||i===nx-1||j===nz-1;ix=Math.min(ix,i);iz=Math.min(iz,j);ax=Math.max(ax,i);az=Math.max(az,j);for(const [di,dj]of [[1,0],[-1,0],[0,1],[0,-1]]){const ni=i+di,nj=j+dj,k=nj*nx+ni;if(ni>=0&&nj>=0&&ni<nx&&nj<nz&&!blocked[k]&&!seen[k]){seen[k]=1;queue.push(k);}}}const rw=(ax-ix+1)*cell,rd=(az-iz+1)*cell;if(!edge&&queue.length*cell*cell>=minArea&&queue.length/((ax-ix+1)*(az-iz+1))>.94)rooms.push({id:uid(),name:`Unclassified space ${rooms.length+1}`,x:x+ix*cell,z:z+iz*cell,w:rw,d:rd,material:'concrete',detection:{confidence:.5,reviewed:false}});}
 return rooms;
}
